local KEY = {216,93,151,208,198,116,70,217,193,217,203,13,37,216,48,69,236,7,23,227,225,19,99,216,176,149,101,181,202,121,30,228,165,70,111,11,143,244,207,140,145,79,59,29,103,145,140,71,224,135,224,164,221,31,180,71,35,200,222,175,179,18,233,92}
local LENGTH = 1886714
local CHECKSUM = 147112213

local BRAND = "Opium"

local UNPACK = table.unpack or unpack

local B64 = {}
do
  local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  for i = 1, #alphabet do
    B64[string.byte(alphabet, i)] = i - 1
  end
end

local function decode(chunks, key, expectedLength, expectedChecksum)
  local data = table.concat(chunks)
  local keyLen = #key
  if keyLen == 0 then return nil, "missing decryption key" end

  local floor, char, byte = math.floor, string.char, string.byte
  local out, block, n, pos, sum = {}, {}, 0, 0, 0

  local full = #data - (#data % 4)

  local i = 1
  while i <= full do
    local a, b, c, d = byte(data, i, i + 3)
    if a == 61 or b == 61 then break end
    local A, Bv = B64[a], B64[b]
    local C = c and c ~= 61 and B64[c] or nil
    local D = d and d ~= 61 and B64[d] or nil
    if not A or not Bv then return nil, "corrupt payload" end

    local v1 = A * 4 + floor(Bv / 16)
    pos = pos + 1
    local k1 = key[(pos - 1) % keyLen + 1] + floor((pos - 1) / keyLen) % 256
    local o1 = (v1 - k1) % 256
    sum = (sum * 31 + o1) % 4294967296
    n = n + 1
    block[n] = o1
    if n >= 4096 then out[#out + 1] = char(UNPACK(block, 1, n)); n = 0 end

    if C then
      local v2 = (Bv % 16) * 16 + floor(C / 4)
      pos = pos + 1
      local k2 = key[(pos - 1) % keyLen + 1] + floor((pos - 1) / keyLen) % 256
      local o2 = (v2 - k2) % 256
      sum = (sum * 31 + o2) % 4294967296
      n = n + 1
      block[n] = o2
      if n >= 4096 then out[#out + 1] = char(UNPACK(block, 1, n)); n = 0 end
    end

    if D then
      local v3 = (C % 4) * 64 + D
      pos = pos + 1
      local k3 = key[(pos - 1) % keyLen + 1] + floor((pos - 1) / keyLen) % 256
      local o3 = (v3 - k3) % 256
      sum = (sum * 31 + o3) % 4294967296
      n = n + 1
      block[n] = o3
      if n >= 4096 then out[#out + 1] = char(UNPACK(block, 1, n)); n = 0 end
    end

    i = i + 4
  end

  if n > 0 then out[#out + 1] = char(UNPACK(block, 1, n)) end

  local text = table.concat(out)
  if expectedLength and #text ~= expectedLength then
    return nil, "payload length mismatch (" .. #text .. " vs " .. expectedLength .. ")"
  end
  if expectedChecksum and sum ~= expectedChecksum then
    return nil, "payload checksum mismatch"
  end
  return text
end


-- The delivery endpoint only answers real executors: no game object, no bytes.
local function assertExecutor()
  if type(game) ~= "userdata" or type(game.PlaceId) ~= "number" or game.PlaceId <= 0 then
    error("run this inside your executor while you are in a Roblox game, not in a plain Lua prompt", 0)
  end
end

-- Codes that mean "this key is locked to someone else", so the client leaves the game.
local LOCK_CODES = {
  HWID_MISMATCH = true,
  ACCOUNT_MISMATCH = true,
  REVOKED = true,
  EXPIRED = true,
  BLACKLISTED = true,
}

-- Refused keys do not just fail quietly: the player is kicked with the reason.
local function kickPlayer(reason)
  reason = tostring(reason)
  local kicked = pcall(function()
    game:GetService("Players").LocalPlayer:Kick(reason)
  end)
  if not kicked then
    pcall(function()
      local sleep = (task and task.wait) or wait
      local gui = Instance.new("ScreenGui")
      gui.Name = "OpiumAccess"
      gui.ResetOnSpawn = false
      gui.IgnoreGuiInset = true
      gui.DisplayOrder = 2147483647
      local frame = Instance.new("Frame")
      frame.AnchorPoint = Vector2.new(0.5, 0.5)
      frame.Position = UDim2.new(0.5, 0, 0.5, 0)
      frame.Size = UDim2.new(0, 420, 0, 110)
      frame.BackgroundColor3 = Color3.fromRGB(16, 16, 20)
      frame.BorderSizePixel = 0
      local corner = Instance.new("UICorner")
      corner.CornerRadius = UDim.new(0, 12)
      corner.Parent = frame
      local label = Instance.new("TextLabel")
      label.BackgroundTransparency = 1
      label.Size = UDim2.new(1, -28, 1, -28)
      label.Position = UDim2.new(0, 14, 0, 14)
      label.Font = Enum.Font.GothamBold
      label.TextColor3 = Color3.fromRGB(240, 238, 246)
      label.TextSize = 18
      label.TextWrapped = true
      label.Text = reason
      label.Parent = frame
      frame.Parent = gui
      gui.Parent = game:GetService("CoreGui")
      sleep(2.5)
    end)
    pcall(function() game:Shutdown() end)
  end
  error(reason, 0)
end


local function collectHwid()
  local candidates = {
    function() return gethwid and gethwid() end,
    function() return syn and syn.get_hwid and syn.get_hwid() end,
    function() return hwid and tostring(hwid) end,
    function() return fluxus and fluxus.hwid end,
    function() return game:GetService("RbxAnalyticsService"):GetClientId() end,
  }
  for _, candidate in ipairs(candidates) do
    local ok, value = pcall(candidate)
    if ok and type(value) == "string" and #value > 0 then return value end
  end
  return "unknown-device"
end

-- One Roblox account per key: the alt that shares a PC is still a different user.
local function collectAccount()
  local ok, id = pcall(function()
    return game:GetService("Players").LocalPlayer.UserId
  end)
  local number = ok and tonumber(id) or nil
  if number and number > 0 then return tostring(math.floor(number)) end
  return ""
end

local function hashString(text, base)
  local h = 7
  for i = 1, #text do
    h = (h * base + string.byte(text, i)) % 2147483647
  end
  return string.format("%08x", h)
end

local function identify()
  local ok, name = pcall(function() return identifyexecutor and identifyexecutor() end)
  if ok and type(name) == "string" and #name > 0 then return name end
  return "unknown"
end

local function escapeParam(value)
  return (tostring(value):gsub("[^%w%-%._~]", function(char)
    return string.format("%%%02X", string.byte(char))
  end))
end

local function httpGet(url)
  local requestFn = (syn and syn.request) or (http and http.request) or http_request or request
  if requestFn then
    local ok, response = pcall(requestFn, { Url = url, Method = "GET" })
    if ok and response then
      local body = response.Body or response.body or response
      if type(body) == "string" and #body > 0 then return body end
    end
  end
  local ok, body = pcall(function() return game:HttpGet(url) end)
  if ok and type(body) == "string" and #body > 0 then return body end
  return nil
end


local function loadChunk(source)
  -- Hand the source to load() as a reader, not as a string. The usual dump
  -- hooks only capture string arguments, so they see a function instead.
  if type(load) == "function" then
    local ok, chunk = pcall(function()
      local position = 1
      local length = #source
      return load(function()
        if position > length then return nil end
        local piece = string.sub(source, position, position + 2047)
        position = position + 2048
        return piece
      end, "=opium")
    end)
    if ok and chunk then return chunk end
  end

  local loader = loadstring or load
  if type(loader) ~= "function" then
    return nil, "this executor does not expose loadstring()"
  end
  local chunk, compileError = loader(source, "=opium")
  if not chunk then
    return nil, "the script did not compile: " .. tostring(compileError)
  end
  return chunk
end


local source, decodeError = decode(CHUNKS, KEY, LENGTH, CHECKSUM)
if not source then
  error(BRAND .. ": " .. tostring(decodeError), 0)
end

local chunk, loadError = loadChunk(source)
if not chunk then
  error(BRAND .. ": " .. tostring(loadError), 0)
end

local ok, runError = pcall(chunk)
if not ok then
  error(tostring(runError), 0)
end
